// Backfill/recarga: preencha os dois com 'YYYY-MM-DD'. Vazios = modo normal.
const DATA_INICIO = '';
const DATA_FIM = '';
const DIAS = 2; // hoje-1 e hoje-2: o dia corrente so fecha depois do turno

// Janela que vai no dia_start da chamada. NAO e' enfeite: a API devolve as
// tarefas com MOVIMENTO dentro de [dia_start, dia_end], e o bloco `acumulado`
// de cada uma e' o estado no dia_end. Janela de 1 dia devolve MENOS tarefa.
// Medido em 21/09/2026 na id_eap 51 (a maior, obra 91), dia_end 19/09:
//     1 dia  -> 54 tarefas, 96s
//    30 dias -> 60 tarefas, 73s
//   180 dias -> nao respondeu em 120s
// Por isso 30. Aumentar so' acrescenta tarefa, nunca troca valor de quem ja
// veio (conferido contra a view), mas passa do que a origem aguenta.
const JANELA_DIAS = 30;

const ISO = /^\d{4}-\d{2}-\d{2}$/;

// Lista de EAPs vem do node anterior (MySQL), nao de constante no codigo:
// entrou obra nova, `eap_tarefas` ja sabe e este fluxo acompanha sozinho.
const eaps = [...new Set(
  $input.all()
    .map(it => Number(it.json.id_eap))
    .filter(v => Number.isInteger(v))
)];
if (!eaps.length) throw new Error('Nenhum id_eap veio do node de listagem — o fluxo nao tem o que buscar.');

const hoje = $now.setZone('America/Sao_Paulo').startOf('day');
const datas = [];
if (DATA_INICIO || DATA_FIM) {
  if (!ISO.test(DATA_INICIO) || !ISO.test(DATA_FIM)) {
    throw new Error('DATA_INICIO e DATA_FIM devem estar os dois preenchidos no formato YYYY-MM-DD');
  }
  let dt = DateTime.fromISO(DATA_INICIO, { zone: 'America/Sao_Paulo' });
  const fim = DateTime.fromISO(DATA_FIM, { zone: 'America/Sao_Paulo' });
  if (fim < dt) throw new Error('DATA_FIM e anterior a DATA_INICIO');
  while (dt <= fim) { datas.push(dt.toFormat('yyyy-MM-dd')); dt = dt.plus({ days: 1 }); }
} else {
  if (!(DIAS >= 1)) throw new Error('DIAS deve ser >= 1');
  for (let k = 1; k <= DIAS; k++) datas.push(hoje.minus({ days: k }).toFormat('yyyy-MM-dd'));
}

const recuar = (diaISO, dias) => DateTime.fromISO(diaISO, { zone: 'America/Sao_Paulo' })
  .minus({ days: dias }).toFormat('yyyy-MM-dd');

const combinacoes = [];
for (const data of datas) {
  for (const id_eap of eaps) {
    combinacoes.push({ json: { id_eap, data, dia_start: recuar(data, JANELA_DIAS) } });
  }
}
return combinacoes;

// `medicao_diaria` NAO e mais alimentada (decidido 21/09/2026). O bloco
// `diario` de cada tarefa so vem quando dia_start == dia_end — com a janela de
// 30 dias (que e o que da cobertura boa no acumulado) ele vem `null` em 100%
// das tarefas, conferido na origem. Alimentar os dois exigiria uma SEGUNDA
// chamada por EAP/dia numa origem que ja leva 73-96s na maior delas. Como
// `medicao_diaria` nao tem nenhum leitor (grep no repo, em `apresentacao/` e
// nas copias legadas do Dropbox, 21/09/2026), a escolha foi cobertura do
// acumulado. A tabela fica no Supabase com o historico ate 20/09, parada.
const par = $('Loop dia x EAP (1 por vez)').first().json;
const dataRefLoop = par.data;
const idEapLoop = par.id_eap;

// A API responde { data: { id_eap, tarefas: [...] } }; o node HTTP pode
// embrulhar de novo. Desembrulha ate achar quem tem `tarefas`.
let corpo = $json;
if (typeof corpo === 'string') { corpo = JSON.parse(corpo); }
if (corpo && typeof corpo.data === 'string') { try { corpo = JSON.parse(corpo.data); } catch (e) { /* nao era JSON */ } }
while (corpo && corpo.data && typeof corpo.data === 'object' && !Array.isArray(corpo.data) && corpo.data.tarefas) { corpo = corpo.data; }
if (corpo && corpo.body && typeof corpo.body === 'object' && corpo.body.tarefas) { corpo = corpo.body; }

const vazio = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
const n = v => { if (vazio(v)) return null; const x = Number(typeof v === 'string' ? v.trim().replace(',', '.') : v); return Number.isFinite(x) ? x : null; };
const i = v => { const x = n(v); return x === null ? null : Math.trunc(x); };
const s = (v, max) => { if (vazio(v) || typeof v === 'object') return null; const t = String(v).trim(); return t.length > max ? t.slice(0, max) : t; };
const b = v => (v === true ? 1 : v === false ? 0 : null);
const d = v => { if (vazio(v)) return null; const t = String(v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null; };
const q = String.fromCharCode(96);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\x00/g, '') + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));

const dataRef = d(dataRefLoop);
if (!dataRef) throw new Error('Data de referencia invalida no loop: ' + dataRefLoop);

const idEap = i(corpo && corpo.id_eap) ?? i(idEapLoop);
if (idEap === null) throw new Error('Sem id_eap utilizavel (loop: ' + idEapLoop + ')');

const tarefas = corpo && Array.isArray(corpo.tarefas) ? corpo.tarefas : null;
if (!tarefas) {
  throw new Error('Formato inesperado em receita_custos/' + idEapLoop + ' (' + dataRef + ') - chaves recebidas: ' + JSON.stringify(Object.keys(corpo || {})));
}

const acumMySql = [];
const acumSupabase = [];
const tarefasSupabase = [];
let descartados = 0;
let amostraRuim = null;

for (const t of tarefas) {
  const tarefaId = i(t.id ?? t.tarefa_id);
  // tarefa sem id nao tem chave: nao da pra gravar nem pra atualizar depois.
  if (tarefaId === null) {
    descartados++;
    if (!amostraRuim) amostraRuim = JSON.stringify(t).slice(0, 400);
    continue;
  }
  const a = t.acumulado || {};

  acumMySql.push({
    data_referencia: dataRef,
    tarefa_id: tarefaId,
    id_eap: idEap,
    receita: n(t.receita),
    custo_incorrido: n(a.custo_incorrido),
    custo_projetado: n(a.custo_projetado),
    avanco_total: n(a.avanco_total),
    efetivo_total: n(a.efetivo_total),
    custo_incorrido_acima_projetado: b(a.custo_incorrido_acima_projetado),
  });

  // Supabase continua recebendo o MESMO formato de antes: `apresentacao/`
  // ainda le a view `v_indices_financeiros_diario`, que sai de
  // `medicao_acumulada` + `tarefas`. Enquanto aquela copia nao migrar, cortar
  // esta escrita quebraria a Performance la.
  acumSupabase.push({
    tarefa_id: tarefaId,
    data_referencia: dataRef,
    custo_incorrido: a.custo_incorrido ?? null,
    custo_projetado: a.custo_projetado ?? null,
    avanco_total: a.avanco_total ?? null,
    efetivo_total: a.efetivo_total ?? null,
    receita: t.receita ?? null,
    custo_incorrido_acima_projetado: a.custo_incorrido_acima_projetado ?? null,
  });

  tarefasSupabase.push({
    id: tarefaId,
    id_eap: idEap,
    codigo_seq: t.codigo_seq ?? null,
    tarefa: t.tarefa ?? null,
    local: t.local ?? null,
    supervisor: t.supervisor ?? null,
    valor_hora: t.valor_hora ?? null,
    hht_previsto_avanco: t.hht_previsto_avanco ?? null,
    hht_consumido: t.hht_consumido ?? null,
    custo_meta_servico_subtotal: t.custo_meta_servico_subtotal ?? null,
    avanco_acumulado: t.avanco_acumulado ?? null,
    avanco_atual_p100_total: t.avanco_atual_p100_total ?? null,
    receita: t.receita ?? null,
    total_efetivo: t.total_efetivo ?? null,
    diario_disponivel: corpo.diario_disponivel ?? false,
  });

}

// Sem isto, mapeamento errado vira carga vazia SEM erro: as linhas somem em
// silencio, o INSERT vira 'SELECT 1' e o fluxo termina verde.
if (tarefas.length > 0 && acumMySql.length === 0) {
  throw new Error('receita_custos/' + idEap + ' ' + dataRef + ': ' + tarefas.length + ' tarefa(s) e NENHUMA com id utilizavel. Amostra: ' + amostraRuim);
}

// As colunas geradas (indice_receita_custo_incorrido, sem_custo) NAO entram no
// INSERT: o MySQL as calcula e recusa valor explicito.
const COLUNAS = ['data_referencia','tarefa_id','id_eap','receita','custo_incorrido','custo_projetado','avanco_total','efetivo_total','custo_incorrido_acima_projetado'];
const CHAVE = ['data_referencia','tarefa_id'];
const colsSql = COLUNAS.map(c => q + c + q).join(',');
const tuplas = acumMySql.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const upd = COLUNAS.filter(c => !CHAVE.includes(c)).map(c => q + c + q + ' = novo.' + q + c + q).join(', ');
// `AS novo` em vez de VALUES(col): VALUES() esta deprecado no MySQL 8.4.
const sqlUpsert = acumMySql.length
  ? 'INSERT INTO fin_medicao_acumulada (' + colsSql + ') VALUES ' + tuplas + ' AS novo ON DUPLICATE KEY UPDATE ' + upd
  : 'SELECT 1';

// Tarefa que saiu da resposta tem que sair do dia. Resposta VAZIA nao apaga
// nada: nao da pra distinguir "dia sem tarefa" de "origem com problema", e a
// origem aqui e reconhecidamente lenta/instavel (73-96s na id_eap 51).
const ids = acumMySql.map(l => l.tarefa_id).join(',');
const sqlDelete = acumMySql.length
  ? 'DELETE FROM fin_medicao_acumulada WHERE data_referencia = ' + sqlVal(dataRef) + ' AND id_eap = ' + idEap + ' AND tarefa_id NOT IN (' + ids + ')'
  : 'SELECT 1';

const diagnostico = {
  id_eap: idEap,
  data_referencia: dataRef,
  janela: { dia_start: par.dia_start, dia_end: par.data },
  tarefas_recebidas: tarefas.length,
  descartadas: descartados,
  linhas_acumulado: acumMySql.length,
};

return [{ json: { acumSupabase, tarefasSupabase, sqlUpsert, sqlDelete, diagnostico } }];
